from vlb_traj import Session
with Session() as s:
    s.record_start()
    q0=np.array([-0.005355354089366387,-0.7070174650173956,0.7071502050763971,-0.006017624395282082])
    rz=Rotation.from_euler('z',90,degrees=True)
    q=(Rotation.from_quat([q0[1],q0[2],q0[3],q0[0]]) * rz).as_quat()
    q=[q[3],q[0],q[1],q[2]]
    p=np.array([-0.07132329312929614,0.13511619738480857,0.8509989378775296])
    print('Q',q)
    def goto(pos,n=40,f=.04):
        ik=s.ik(pos,q); print('IK',pos,ik['success'])
        if not ik['success']: raise RuntimeError('IK failed')
        goal=np.asarray(ik['joint_positions']); start=np.asarray(s.state()['robot']['joint_positions'])
        for t in np.linspace(0,1,n+1)[1:]: s.step(list(start+(goal-start)*t)+[f,f])
        for _ in range(8): s.step(list(goal)+[f,f])
    goto(p+[0,0,.06])
    print('APPROACH',s.state()['robot']['tcp_position'])
