            for t in np.linspace(0,1,41)[1:]: s.step(list(start+(end-start)*t)+[.001,.001])
            for _ in range(10): s.step(list(end)+[.001,.001])
    print('FINAL',s.status(),s.state()['entities']['ace_of_hearts'],s.state()['robot'])
    a=s.record_stop()
    if s.status()['success']:
