import numpy as np
from vlb_traj import Session
with Session() as s:
    s.record_start()
    q=[-0.005355354089366387,-0.7070174650173956,0.7071502050763971,-0.006017624395282082]
    p=np.array([-0.07132329312929614,0.13511619738480857,0.8509989378775296])
    def joint_move(pos,n=35,f=.04):
        ik=s.ik(pos,q); print('IK',pos,ik['success'])
        if not ik['success']: raise RuntimeError('IK failed')
        goal=np.array(ik['joint_positions']); start=np.array(s.state()['robot']['joint_positions'])
        for t in np.linspace(0,1,n+1)[1:]: s.step(list(start+(goal-start)*t)+[f,f])
        for _ in range(5): s.step(list(goal)+[f,f])
    joint_move(p+[0,-.10,0],50)
    print('STAGE',s.state()['robot']['tcp_position'],s.state()['entities']['ace_of_hearts']['position'])
    for dy in np.linspace(-.10,0,21)[1:]:
        joint_move(p+[0,dy,0],5)
    print('CONTACT',s.state()['robot']['tcp_position'],s.state()['entities']['ace_of_hearts'])
    for f in [.03,.02,.01,.005,.001]:
        for _ in range(10): s.step(list(s.state()['robot']['joint_positions'])+[f,f])
        print('CLOSE',f,s.state()['robot']['gripper_positions'],s.state()['entities']['ace_of_hearts']['position'],s.status()['success'])
    if s.status()['success']:
        joint_move(p+[0,0,.13],50,f=.001)
    print('FINAL',s.status(),s.state()['entities']['ace_of_hearts'],s.state()['robot'])
    a=s.record_stop()
    if s.status()['success']:
        s.save_trajectory(a,'/app/output/trajectory.npz'); print('SAVED',a.shape)
    else: print('FAILED',a.shape)
